formulas.expression:
IF(
    ISPICKVAL({!recordId.StageName}, 'Prospect'), 1,
    IF(
        ISPICKVAL({!recordId.StageName}, 'Qualified'), 2,
        IF(
            ISPICKVAL({!recordId.StageName}, 'Pricing'), 3,
            IF(
                ISPICKVAL({!recordId.StageName}, 'Verbal Win'), 4,
                5
            )
        )
    )
)
